from pathlib import Path
R=Path(__file__).parent; raw=json.loads((R/'data/rdf-records.json').read_text()); U={}
# Evidence imported from the supplied bibliography is explicitly attributed.
sim={1,4,7,21,24,27,30,39}
for p in raw:
 n=int(p['id'].split('_')[1]); U[p['id']]={'evidence':'Simulation · RDF report' if n in sim else 'Hardware · RDF report','setting':'Simulation only, according to supplied review.' if n in sim else 'Physical experiments reported in supplied review; lab/outdoor conditions not independently checked.','order':'Not specified in imported review; model order is not inferred from the use of RL.','architecture':p['notes'].split('Method and idea:')[-1].split('Achievements and evidence:')[0].strip(),'overview':'','environment':'Earth gravity / terrestrial research (RDF context).'}
U['item_32']['evidence']='Evidence pending verification'
for n in [44,45]: U['item_'+str(n)].update(evidence='Earth-based gravity testbed · RDF',environment='Extraterrestrial target; simulation / testbed on Earth.',setting='SpaceBok gravity-emulation experiments; no off-world deployment established.')
