A=[]
def add(id,title,year,group,method,url,overview,achievement,gap,evidence,setting,order,architecture,video='',verification='Primary abstract checked 29 Sep 2026.',environment='Earth gravity / terrestrial robotics.',sources=None):
 A.append(dict(id=id,title=title,year=year,group=group,method=method,url=url,overview=overview,achievement=achievement,gap=gap,evidence=evidence,setting=setting,order=order,architecture=architecture,video=video,videoLabel='Author project & videos',verification=verification,environment=environment,origin='Added in this survey',sources=sources or [{'url':url,'label':'Primary paper'}]))
g='Generative control & expert policies'
add('dial-mpc','Full-Order Sampling-Based MPC for Torque-Level Locomotion Control via Diffusion-Style Annealing','2024',g,'Model-based · full-order MPC','https://arxiv.org/abs/2409.15610','DIAL-MPC refines sampled actions online using diffusion-inspired annealing. It does not train a diffusion policy.','Go2 hardware performs sequential jumping with a 7 kg payload. Appendix setup uses 50 Hz planning and 200 Hz low-level commands.','Fast parallel simulation and a short planning horizon constrain the approach. Desktop computation and motion capture limit claims about autonomous field deployment.','Hardware · lab','Go2; offboard RTX 4090 desktop, Ethernet and motion capture.','Full-order articulated dynamics.','Sampling-based receding-horizon control; direct torque output.','https://github.com/LeCAR-Lab/dial-mpc/blob/main/README.md',verification='Full text: Fig. 7, conclusion and Appendix A checked; preprint 2024 / ICRA 2025.',sources=[{'url':'https://arxiv.org/html/2409.15610v1','label':'Full text and setup'}])
add('diffuseloco','DiffuseLoco: Real-Time Legged Locomotion Control with Diffusion from Offline Datasets','2024',g,'Diffusion · offline imitation','https://arxiv.org/abs/2404.19264','Learns a multi-skill locomotion policy from offline data, using a receding action horizon.','Reports real quadruped deployment, transitions between locomotion skills, and edge-device execution.','This demonstrates locomotion-policy synthesis; it does not establish arbitrary precision flips or terrain-aware pronking sequences. Dataset coverage and action-generation latency remain relevant.','Hardware','Quadruped physical locomotion demonstrations; controlled evaluations.','No explicit online dynamics optimizer; data-driven action policy.','Offline diffusion policy with receding-horizon execution.','https://diffuselo.co/',verification='Author project and abstract checked; CoRL 2024.')
add('contact-diffusion','Diffusion-based learning of contact plans for agile locomotion','2024',g,'Diffusion · MCTS · NMPC','https://arxiv.org/abs/2403.03639','Search generates feasible contact plans; diffusion learns their multiple possible solutions and supplies a whole-body controller.','Simulated Solo12 selects contact sequences for jumping on sparse stepping stones.','Hardware implementation remains future work in v5. Known terrain, restricted gait search and low success on a difficult changing-stone task limit generalization claims.','Simulation only','Solo12 simulation; not a physical stepping-stone demonstration.','Whole-body nonlinear MPC.','High-level diffusion contact planner + low-level NMPC.','',verification='v5 full text, including conclusion, checked (23 June 2025). First preprint 2024 used a different title.',sources=[{'url':'https://arxiv.org/html/2403.03639v5','label':'v5 full text'}])
add('dynaflow','DynaFlow: Dynamics-embedded Flow Matching for Physically Consistent Motion Generation from State-only Demonstrations','2025',g,'Flow matching · differentiable simulation','https://arxiv.org/abs/2509.19804','Maps generated actions through a differentiable simulator so learning can use state-only demonstrations.','Physical Go1 reproduces varied gaits and stylistic motions; the project reports long-horizon open-loop execution.','Consistency is with the embedded model. It does not guarantee disturbance recovery in the real world or establish a closed-loop acrobatic pronking system.','Hardware','Go1 physical motion demonstrations.','Dynamics embedded through differentiable simulation.','Flow-matching action generation trained through a simulator.','https://sowoolee.github.io/dynaflow/',verification='Author project checked; 2025 preprint / ICRA 2026.',sources=[{'url':'https://sowoolee.github.io/dynaflow/','label':'Author method and experiments'}])
add('dmloco','Integrating Diffusion-based Multi-task Learning with Online Reinforcement Learning for Robust Quadruped Robot Control','2025',g,'Diffusion · PPO fine-tuning','https://arxiv.org/abs/2507.05674','DMLoco combines offline multi-task diffusion training with reinforcement-learning refinement.','The abstract reports language-conditioned skills, more stable task transitions and onboard inference at 50 Hz.','This is adjacent multi-skill locomotion evidence. The abstract alone does not establish acrobatic landing accuracy or unseen-terrain pronking reliability.','Hardware reported','Real-world deployment reported in abstract; detailed test setting not audited.','No explicit online physics planner described.','Diffusion pretraining + PPO in simulation + onboard policy.',verification='arXiv v2 abstract checked (September 2025); experimental tables not audited.')
add('moe-parkour','Quadruped Parkour Learning: Sparsely Gated Mixture of Experts with Visual Input','2026',g,'RL · sparse mixture of experts','https://arxiv.org/abs/2604.19344','A sparse expert network allocates computation conditionally inside a vision-based parkour policy.','On a 32 cm box, MoE succeeds in 10/10 trials versus 5/10 for an MLP with matched active parameters. Outdoor obstacle demonstrations are included.','Small trial counts do not establish field reliability. Expert selection adds tuning. The reported speed comparison uses batch size 6000, not simply onboard latency.','Hardware · lab + outdoor','Go2 + D435f camera; policy runs offboard on RTX 2060.','Simulation-trained policy, no explicit online dynamics optimization.','Depth-conditioned RL with sparse MoE actor.',verification='Full text: Table III, hardware setup, outdoor tests and conclusion checked.',sources=[{'url':'https://arxiv.org/html/2604.19344v1','label':'Experiments and limitations'}])
add('abot','Behavior Foundations for Quadruped Robots: ABot-C0 Technical Report','2026',g,'Flow matching · multi-policy system','https://arxiv.org/abs/2607.07370','Transfers the large-data motion-tracking recipe prominent in humanoids to quadruped behavior learning.','Reports 16,074 feasible motion clips, a flow-matching motion-tracking policy, and real-world navigation / interaction experiments.','Generalist tracking and urban navigation are not quantitative proof of arbitrary flips, precise repeated landings, or low-gravity performance. Independent replication is not assessed.','Hardware reported','Urban-terrain navigation and interaction; detailed experiment audit pending.','Data-driven tracking; underlying simulator order not audited.','Flow tracking + privileged-to-perceptive locomotion + multi-policy coordination.',verification='July 2026 arXiv v2 technical-report abstract checked; author claims, not independent replication.')
